<div id="items">
<?php $selectedIds=old('product_id',[]);$selectedVariants=old('variant_id',[]);$selectedQty=old('quantity',[]);if(!is_array($selectedIds)||!count($selectedIds)){$selectedIds=[''];$selectedVariants=[''];$selectedQty=[''];} foreach($selectedIds as $i=>$sid): ?>
