<script>
function variantLabel(v){try{const o=typeof v.attributes_json==='string'?JSON.parse(v.attributes_json||'{}'):(v.attributes_json||{});const parts=Object.entries(o||{}).map(([k,val])=>{const label=k.replace(/[_-]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());if(val&&typeof val==='object'&&Object.prototype.hasOwnProperty.call(val,'value'))return label+': '+val.value+(val.unit?' '+val.unit:'');return label+': '+(typeof val==='object'?JSON.stringify(val):val);});return parts.join(' · ')||v.variant_name||'Default';}catch(e){return v.variant_name||'Variant';}}

const variantMap=<?=json_encode($variantMap??[],JSON_UNESCAPED_UNICODE)?>; const variantStockMap=<?=json_encode($variantStockMap??[],JSON_NUMERIC_CHECK)?>; const type='<?=esc($type)?>'; const savedVariants=<?=json_encode(old('variant_id',[]),JSON_UNESCAPED_UNICODE)?>; const itemBox=document.getElementById('items'); const template=itemBox.firstElementChild.outerHTML;
function variantsForProduct(productId){return Object.values(variantMap).filter(v=>String(v.product_id)===String(productId));}
function updateRow(row, savedVariant=''){const ps=row.querySelector('[data-product-select]'), vs=row.querySelector('[data-variant-select]'), q=row.querySelector('[data-qty]'), stock=row.querySelector('[data-stock-label]'), help=row.querySelector('[data-variant-help]'); const list=variantsForProduct(ps.value); const current=savedVariant||vs.value; vs.innerHTML='<option value="">Select size / variant</option>'+list.map(v=>{const label=variantLabel(v);return '<option value="'+v.id+'" '+(String(v.id)===String(current)?'selected':'')+'>'+label+'</option>'}).join(''); if(!list.length){vs.innerHTML='<option value="">No variants configured</option>';help.textContent='Edit the product and add at least one variant.';}else help.textContent=list.length+' variant'+(list.length===1?'':'s')+' available.'; const v=variantMap[vs.value]; if(type==='OUT'&&v){const av=Number(variantStockMap[v.id]||0);stock.textContent='Available · '+Math.round(av).toLocaleString()+' '+(variantProductUnit(v.product_id)||'units');}else stock.textContent=v?'Selected variant':'Available — select variant';}
function variantProductUnit(pid){const p=<?=json_encode(array_reduce($products,function($carry,$p){$carry[$p['id']]=$p['unit'];return $carry;},[]),JSON_UNESCAPED_UNICODE)?>;return p[pid]||'';}
function bind(row, savedVariant=''){row.querySelector('[data-remove-item]')?.addEventListener('click',()=>{if(itemBox.children.length>1)row.remove()});row.querySelector('[data-product-select]').addEventListener('change',()=>updateRow(row));row.querySelector('[data-variant-select]').addEventListener('change',()=>updateRow(row));row.querySelector('[data-qty]').addEventListener('input',()=>updateRow(row));updateRow(row,savedVariant);}
[...itemBox.children].forEach((r,i)=>bind(r,savedVariants[i]||''));document.querySelector('[data-add-item]')?.addEventListener('click',()=>{const d=document.createElement('div');d.innerHTML=template;const r=d.firstElementChild;r.querySelectorAll('input').forEach(i=>i.value='');r.querySelector('[data-product-select]').selectedIndex=0;r.querySelector('[data-variant-select]').innerHTML='<option value="">Select product first</option>';itemBox.appendChild(r);bind(r)});
</script>
